head.script:
scwin.testM = function(f, vf) {
    return "main";
}
scwin.test1 = function(f, vf) {
    return "main";
}
scwin.test2 = function(f, vf) {
    return "main";
}
scwin.checktype1 = function() {
    return typeof WebSquare.wUnit.getDomById('w1_wq_uuid_7_body_table');
}
scwin.checktype2 = function() {
    return typeof WebSquare.wUnit.getDomById('w1_w11_wq_uuid_14_body_table');
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 main2.xml 을 실행시 킨다.
    //1. When running main2.xml in a browser It is.
    //Verify 1. 정상적으로 화면이 표시된다.
    //1. The screen is displayed normally.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype1()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "object");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //w1.setSrc("displayFormatter.xml");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
